//! Deterministic rendering of descriptor-owned module assets.
//!
//! Rendering consumes only the canonical descriptor and its checked projections. Core
//! bindings are supplied as already-owned checked assets and are never regenerated by
//! this path. Every emitted byte is assigned one semantic owner and input domain before
//! the manifest is rendered last.

use std::collections::BTreeMap;

use serde::Serialize;

use super::canonical::{DigestDomain, canonical_bytes, canonical_digest};
use super::diagnostic::{ModuleDiagnostic, ModuleDiagnosticCode, ModuleDiagnosticSet};
use super::metadata::{
    CachePolicy, ExecutionKind, FunctionKind, FunctionReturn, FunctionRole, ReceiverKind,
};
use super::model::{
    GeneratedAsset, GeneratedAssetOwner, GeneratedAssetPath, GeneratedModuleAssets,
    LocalTypeContract, LocalTypeKind, ModuleDescriptor, ModuleIntrospection, ProjectedArgument,
    ProjectedFunction, ProjectedTypeDef, ProjectedTypeKind, RegenerationClass,
    RegistrationProjection, RustSymbol, Sha256Digest, SourceCoordinate,
};
use super::types::{ProjectedType, RustModuleType};

const MANIFEST_PATH: &str = "src/dagger_generated/generated-module-assets.json";

/// Complete in-memory candidate tree ready for failure-atomic publication.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct RenderedModuleAssets {
    /// Every owned output including the manifest bytes.
    pub files: BTreeMap<GeneratedAssetPath, Vec<u8>>,
    /// Ownership and regeneration metadata published last.
    pub manifest: GeneratedModuleAssets,
}

/// Inputs to deterministic generated-module rendering.
pub struct ModuleRenderRequest<'a> {
    /// Canonical module descriptor.
    pub descriptor: &'a ModuleDescriptor,
    /// Descriptor-derived registration projection.
    pub registration: &'a RegistrationProjection,
    /// Structurally equivalent module introspection.
    pub introspection: &'a ModuleIntrospection,
    /// Actual Cargo dependency alias selected by project initialization.
    pub sdk_dependency_alias: &'a str,
    /// Checked binding assets reused without regeneration.
    pub checked_bindings: &'a BTreeMap<GeneratedAssetPath, Vec<u8>>,
}

/// Pure generated-module renderer.
pub struct ModuleRenderer;

impl ModuleRenderer {
    /// Renders a complete candidate tree and ownership manifest atomically in memory.
    pub fn render(
        request: ModuleRenderRequest<'_>,
    ) -> Result<RenderedModuleAssets, ModuleDiagnosticSet> {
        validate_alias(request.sdk_dependency_alias)?;
        if request.registration.descriptor_digest != request.descriptor.digest
            || request.introspection.descriptor_digest != request.descriptor.digest
            || request.registration.types != request.introspection.types
        {
            return Err(singleton(diag(
                ModuleDiagnosticCode::ProjectionMismatch,
                "generated assets received incompatible descriptor projections",
                "project registration and introspection from the same descriptor",
            )));
        }

        let mut files = BTreeMap::new();
        let mut metadata = BTreeMap::new();
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/mod.rs",
            generated_source(
                request.descriptor,
                render_mod(request.sdk_dependency_alias, request.checked_bindings),
            )?,
            GeneratedAssetOwner::Descriptor,
            request.descriptor.source_digest.clone(),
            RegenerationClass::Authoring,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/module_context.rs",
            generated_source(
                request.descriptor,
                render_context(request.sdk_dependency_alias),
            )?,
            GeneratedAssetOwner::Context,
            request.descriptor.target.visible_schema_digest.clone(),
            RegenerationClass::VisibleSchema,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/module_descriptor.rs",
            generated_source(request.descriptor, render_descriptor(request.descriptor))?,
            GeneratedAssetOwner::Descriptor,
            request.descriptor.digest.clone(),
            RegenerationClass::Authoring,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/module_registration.rs",
            generated_source(
                request.descriptor,
                render_registration(
                    request.descriptor,
                    request.registration,
                    request.sdk_dependency_alias,
                )?,
            )?,
            GeneratedAssetOwner::Registration,
            request.descriptor.digest.clone(),
            RegenerationClass::Authoring,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/module_codec.rs",
            generated_source(request.descriptor, render_codecs(request.descriptor)?)?,
            GeneratedAssetOwner::Dispatch,
            request.descriptor.digest.clone(),
            RegenerationClass::Authoring,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/module_dispatch.rs",
            generated_source(request.descriptor, render_dispatch(request.descriptor)?)?,
            GeneratedAssetOwner::Dispatch,
            request.descriptor.digest.clone(),
            RegenerationClass::Authoring,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/module-introspection.json",
            canonical_bytes(request.introspection).map_err(|_| singleton(generation_error()))?,
            GeneratedAssetOwner::Introspection,
            request.descriptor.digest.clone(),
            RegenerationClass::Authoring,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/dagger_generated/binding-catalog.json",
            render_binding_catalog(request.descriptor)?,
            GeneratedAssetOwner::BindingCatalog,
            request.descriptor.target.visible_schema_digest.clone(),
            RegenerationClass::VisibleSchema,
        )?;
        insert(
            &mut files,
            &mut metadata,
            "src/bin/dagger-module.rs",
            generated_source(request.descriptor, render_entrypoint(request.descriptor))?,
            GeneratedAssetOwner::Entrypoint,
            request.descriptor.generator_digest.clone(),
            RegenerationClass::Generator,
        )?;

        for (path, content) in request.checked_bindings {
            if files.contains_key(path) || path.as_str() == MANIFEST_PATH {
                return Err(singleton(diag(
                    ModuleDiagnosticCode::GeneratedOwnershipConflict,
                    "a checked binding collides with a module-owned generated path",
                    "retain unique ownership for checked bindings and module assets",
                )));
            }
            files.insert(path.clone(), content.clone());
            metadata.insert(
                path.clone(),
                GeneratedAsset {
                    path: path.clone(),
                    digest: Sha256Digest::hash_bytes(content),
                    owner: GeneratedAssetOwner::VisibleBinding,
                    input_digest: request.descriptor.target.visible_schema_digest.clone(),
                    regeneration: RegenerationClass::VisibleSchema,
                },
            );
        }

        let manifest_path =
            GeneratedAssetPath::new(MANIFEST_PATH).map_err(|_| singleton(generation_error()))?;
        let placeholder = Sha256Digest::hash_bytes(b"pending generated asset manifest digest");
        let mut manifest = GeneratedModuleAssets {
            format_version: request.descriptor.format_version,
            target: request.descriptor.target.clone(),
            descriptor_digest: request.descriptor.digest.clone(),
            manifest_path: manifest_path.clone(),
            assets: metadata,
            digest: placeholder,
        };
        manifest.digest = manifest_digest(&manifest).map_err(|_| singleton(generation_error()))?;
        validate_manifest(&manifest)?;
        let manifest_bytes =
            canonical_bytes(&manifest).map_err(|_| singleton(generation_error()))?;
        files.insert(manifest_path, manifest_bytes);
        Ok(RenderedModuleAssets { files, manifest })
    }
}

/// Computes manifest identity without recursively including its identity field.
pub fn manifest_digest(
    manifest: &GeneratedModuleAssets,
) -> Result<Sha256Digest, super::canonical::CanonicalError> {
    let mut value =
        serde_json::to_value(manifest).map_err(super::canonical::CanonicalError::Encode)?;
    if let serde_json::Value::Object(object) = &mut value {
        object.remove("digest");
    }
    canonical_digest(DigestDomain::GeneratedAssets, &value)
}

/// Verifies the acyclic manifest identity and every key-to-record ownership invariant.
pub fn validate_manifest(manifest: &GeneratedModuleAssets) -> Result<(), ModuleDiagnosticSet> {
    let digest_matches = manifest_digest(manifest)
        .map(|digest| digest == manifest.digest)
        .unwrap_or(false);
    let assets_are_consistent = !manifest.assets.is_empty()
        && manifest.assets.iter().all(|(path, asset)| {
            path == &asset.path
                && path != &manifest.manifest_path
                && asset.owner != GeneratedAssetOwner::Manifest
        });
    if digest_matches && assets_are_consistent {
        Ok(())
    } else {
        Err(singleton(diag(
            ModuleDiagnosticCode::GeneratedAssetsStale,
            "generated asset ownership metadata is internally inconsistent",
            "regenerate the complete module tree with the current manifest format",
        )))
    }
}

fn insert(
    files: &mut BTreeMap<GeneratedAssetPath, Vec<u8>>,
    metadata: &mut BTreeMap<GeneratedAssetPath, GeneratedAsset>,
    path: &str,
    content: Vec<u8>,
    owner: GeneratedAssetOwner,
    input_digest: Sha256Digest,
    regeneration: RegenerationClass,
) -> Result<(), ModuleDiagnosticSet> {
    let path = GeneratedAssetPath::new(path).map_err(|_| singleton(generation_error()))?;
    let digest = Sha256Digest::hash_bytes(&content);
    if files.insert(path.clone(), content).is_some() {
        return Err(singleton(diag(
            ModuleDiagnosticCode::GeneratedOwnershipConflict,
            "a renderer emitted one generated path more than once",
            "assign every generated path to exactly one semantic owner",
        )));
    }
    metadata.insert(
        path.clone(),
        GeneratedAsset {
            path,
            digest,
            owner,
            input_digest,
            regeneration,
        },
    );
    Ok(())
}

fn generated_source(
    descriptor: &ModuleDescriptor,
    body: Vec<u8>,
) -> Result<Vec<u8>, ModuleDiagnosticSet> {
    let body = String::from_utf8(body).map_err(|_| singleton(generation_error()))?;
    let source = format!(
        "// @generated by the Dagger Rust module compiler; do not edit.\n// descriptor: {}\n// generator: {}\n",
        descriptor.digest.as_str(),
        descriptor.generator_digest.as_str()
    ) + &body;
    checked_source(source)
}

fn checked_source(source: String) -> Result<Vec<u8>, ModuleDiagnosticSet> {
    syn::parse_file(&source).map_err(|_| singleton(generation_error()))?;
    Ok(source.into_bytes())
}

fn render_mod(alias: &str, checked_bindings: &BTreeMap<GeneratedAssetPath, Vec<u8>>) -> Vec<u8> {
    let mut source = format!(
        "//! Generated module support for the checked authoring descriptor.\n\n\
         #[doc(hidden)]\npub mod __private {{\n    pub use {alias}::__private::*;\n}}\n\n\
         mod module_codec;\nmod module_context;\nmod module_descriptor;\nmod module_dispatch;\nmod module_registration;\n\n\
         #[doc(hidden)]\npub use module_dispatch::GeneratedDispatchRegistry;\n\
         #[doc(hidden)]\npub use module_registration::GeneratedRegistrationSink;\n\n\
         pub use {alias}::{{CurrentCall, ModuleCancellation, ModuleError, ModuleErrorDetail, TelemetryContext}};\n\
         pub use module_context::{{ModuleContext, ModuleQuery}};\n"
    );
    for path in checked_bindings.keys().filter(|path| {
        path.as_str().starts_with("src/dagger_generated/")
            && path.as_str().ends_with(".rs")
            && path.as_str() != "src/dagger_generated/mod.rs"
    }) {
        let file = path
            .as_str()
            .rsplit_once('/')
            .map_or(path.as_str(), |(_, file)| file);
        let module = file.strip_suffix(".rs").unwrap_or(file);
        let module = if syn::parse_str::<syn::Ident>(module).is_ok() {
            module.to_owned()
        } else {
            format!("r#{module}")
        };
        source.push_str(&format!(
            "#[path = {file:?}]\nmod {module};\npub use {module}::*;\n"
        ));
    }
    source.into_bytes()
}

fn render_context(alias: &str) -> Vec<u8> {
    format!(
        "//! Generated call-scoped context for the checked visible schema.\n\n\
         /// Call-scoped access to the active module session and runtime context.\n#[derive(Clone)]\npub struct ModuleContext {{\n    inner: {alias}::__private::ModuleContextBase,\n    query: ModuleQuery,\n}}\n\n\
         /// Query root bound to the same active session as the current call.\n#[derive(Clone)]\npub struct ModuleQuery {{\n    root: {alias}::Query,\n}}\n\n\
         impl ModuleContext {{\n    #[doc(hidden)]\n    pub fn from_base(inner: {alias}::__private::ModuleContextBase) -> Self {{\n        let query = ModuleQuery {{ root: inner.query_builder().generated_query_root() }};\n        Self {{ inner, query }}\n    }}\n\n    /// Borrows the generated query root for the active session.\n    pub fn query(&self) -> &ModuleQuery {{ &self.query }}\n    /// Returns the active engine function-call handle without reconnecting.\n    pub fn current_function_call(&self) -> {alias}::FunctionCall {{ self.query.current_function_call() }}\n    /// Returns the module currently served by this active session.\n    pub fn current_module(&self) -> {alias}::CurrentModule {{ self.query.current_module() }}\n    /// Returns the engine-held receiver for this instance call.\n    pub fn current_node(&self) -> {alias}::NodeClient {{ self.query.current_node() }}\n    /// Borrows this call's monotonic cancellation signal.\n    pub fn cancellation(&self) -> &{alias}::ModuleCancellation {{ self.inner.cancellation() }}\n    /// Borrows the telemetry context inherited by this call.\n    pub fn telemetry_context(&self) -> &{alias}::TelemetryContext {{ self.inner.telemetry_context() }}\n    /// Borrows stable coordinates for the current call.\n    pub fn current_call(&self) -> &{alias}::CurrentCall {{ self.inner.current_call() }}\n}}\n\n\
         impl ::core::ops::Deref for ModuleQuery {{\n    type Target = {alias}::Query;\n\n    fn deref(&self) -> &Self::Target {{ &self.root }}\n}}\n"
    )
    .into_bytes()
}

fn render_descriptor(descriptor: &ModuleDescriptor) -> Vec<u8> {
    let mut output = String::from("//! Generated static descriptor view.\n\n");
    for (index, function) in descriptor.functions.iter().enumerate() {
        output.push_str(&format!(
            "static ARGUMENTS_{index}: &[super::__private::ArgumentView] = &[\n"
        ));
        for argument in &function.compiled.arguments {
            let default_json = argument
                .metadata
                .default
                .as_ref()
                .map(|value| format!("Some({:?})", value.to_string()))
                .unwrap_or_else(|| "None".to_owned());
            output.push_str(&format!(
                "    super::__private::ArgumentView {{ wire_name: {:?}, required: {}, default_json: {default_json} }},\n",
                argument.wire_name.as_str(),
                !argument.metadata.optional && argument.metadata.default.is_none()
            ));
        }
        output.push_str("];\n");
    }
    output.push_str("\nstatic TYPES: &[super::__private::ModuleTypeView] = &[\n");
    for ty in &descriptor.types {
        let kind = match ty.kind {
            LocalTypeKind::Object { .. } => "Object",
            LocalTypeKind::Interface => "Interface",
            LocalTypeKind::Enum => "Enum",
            LocalTypeKind::Scalar { .. } => "Scalar",
        };
        output.push_str(&format!(
            "    super::__private::ModuleTypeView {{ wire_name: {:?}, kind: super::__private::ModuleTypeKindView::{kind} }},\n",
            ty.wire_name.as_str()
        ));
    }
    output.push_str("];\n\nstatic FUNCTIONS: &[super::__private::FunctionView] = &[\n");
    for (index, function) in descriptor.functions.iter().enumerate() {
        let parent = descriptor
            .types
            .iter()
            .find(|ty| ty.rust_symbol == function.parent)
            .map_or("", |ty| ty.wire_name.as_str());
        output.push_str(&format!(
            "    super::__private::FunctionView {{ parent_wire_name: {parent:?}, function_wire_name: {:?}, constructor: {}, arguments: ARGUMENTS_{index}, result_type: {:?} }},\n",
            function.wire_name.as_str(),
            function.compiled.kind == FunctionKind::Constructor,
            rust_type(function.compiled.return_type.success())
        ));
    }
    let root = descriptor
        .types
        .iter()
        .find(|ty| ty.rust_symbol == descriptor.root)
        .map_or("", |ty| ty.wire_name.as_str());
    output.push_str(&format!(
        "];\n\npub static DESCRIPTOR: super::__private::ModuleDescriptorView = super::__private::ModuleDescriptorView {{\n    digest: {:?},\n    root_wire_name: {root:?},\n    types: TYPES,\n    functions: FUNCTIONS,\n}};\n",
        descriptor.digest.as_str()
    ));
    output.into_bytes()
}

fn render_registration(
    descriptor: &ModuleDescriptor,
    registration: &RegistrationProjection,
    alias: &str,
) -> Result<Vec<u8>, ModuleDiagnosticSet> {
    let json = String::from_utf8(
        canonical_bytes(registration).map_err(|_| singleton(generation_error()))?,
    )
    .map_err(|_| singleton(generation_error()))?;
    let mut output = format!(
        "//! Generated complete registration projection and active-session sink.\n\n\
         pub static REGISTRATION: super::__private::RegistrationView = super::__private::RegistrationView {{ descriptor_digest: {:?}, canonical_json: {:?} }};\n\n\
         /// Descriptor-specific registration publisher bound to one active query root.\n\
         pub struct GeneratedRegistrationSink {{ query: {alias}::Query }}\n\n\
         impl GeneratedRegistrationSink {{\n    /// Binds registration to the existing module session.\n    pub fn new(query: {alias}::Query) -> Self {{ Self {{ query }} }}\n}}\n\n\
         impl super::__private::RegistrationSink for GeneratedRegistrationSink {{\n    fn serve<'a>(&'a self, registration: &'a super::__private::RegistrationView) -> super::__private::ModuleBoxFuture<'a, Result<(), super::__private::RegistrationError>> {{\n        Box::pin(async move {{\n            if registration.descriptor_digest != REGISTRATION.descriptor_digest {{\n                return Err(super::__private::RegistrationError::new());\n            }}\n            let query = self.query.clone();\n            let mut module = query.module();\n",
        registration.descriptor_digest.as_str(),
        json
    );

    let root_wire_name = descriptor
        .types
        .iter()
        .find(|ty| ty.rust_symbol == descriptor.root)
        .map(|ty| ty.wire_name.as_str())
        .ok_or_else(|| singleton(generation_error()))?;
    let query_type = registration
        .types
        .values()
        .find(|ty| ty.wire_name.as_str() == "Query")
        .ok_or_else(|| singleton(generation_error()))?;
    let constructor = query_type
        .functions
        .iter()
        .find(|function| function.constructor)
        .ok_or_else(|| singleton(generation_error()))?;

    for ty in registration
        .types
        .values()
        .filter(|ty| ty.wire_name.as_str() != "Query")
    {
        let variable = format!("type_{}", ty.wire_name.as_str().to_ascii_lowercase());
        output.push_str(&format!(
            "            let mut {variable} = {};\n",
            render_type_definition(ty, alias)
        ));
        for field in &ty.fields {
            let options = render_field_options(field, alias);
            output.push_str(&format!(
                "            {variable} = {variable}.with_field_opts({:?}, {}, &{options});\n",
                field.wire_name.as_str(),
                render_projected_type(&field.ty, descriptor, alias)?
            ));
        }
        for function in &ty.functions {
            if !function.constructor {
                output.push_str(&render_function(
                    &variable, function, descriptor, alias, false,
                )?);
            }
        }
        if ty.wire_name.as_str() == root_wire_name {
            output.push_str(&render_function(
                &variable,
                constructor,
                descriptor,
                alias,
                true,
            )?);
        }
        let attach = match ty.kind {
            ProjectedTypeKind::Object => "with_object",
            ProjectedTypeKind::Interface => "with_interface",
            ProjectedTypeKind::Enum => "with_enum",
            ProjectedTypeKind::Scalar => continue,
        };
        output.push_str(&format!(
            "            module = module.{attach}({variable});\n"
        ));
    }
    output.push_str(
        "            module.serve().await.map_err(super::__private::RegistrationError::with_source)\n        })\n    }\n}\n",
    );
    Ok(output.into_bytes())
}

fn render_type_definition(ty: &ProjectedTypeDef, alias: &str) -> String {
    let query = "query";
    let source = render_source_map(query, &ty.source);
    match ty.kind {
        ProjectedTypeKind::Object => {
            let mut options = format!("{alias}::TypeDefWithObjectOpts::default()");
            append_string_option(
                &mut options,
                "with_description",
                ty.documentation.as_deref(),
            );
            append_string_option(&mut options, "with_deprecated", ty.deprecation.as_deref());
            options.push_str(&format!(".with_source_map({source}.into())"));
            format!(
                "{query}.type_def().with_object_opts({:?}, &{options})",
                ty.wire_name.as_str()
            )
        }
        ProjectedTypeKind::Interface => {
            let mut options = format!("{alias}::TypeDefWithInterfaceOpts::default()");
            append_string_option(
                &mut options,
                "with_description",
                ty.documentation.as_deref(),
            );
            options.push_str(&format!(".with_source_map({source}.into())"));
            format!(
                "{query}.type_def().with_interface_opts({:?}, &{options})",
                ty.wire_name.as_str()
            )
        }
        ProjectedTypeKind::Enum => {
            let mut options = format!("{alias}::TypeDefWithEnumOpts::default()");
            append_string_option(
                &mut options,
                "with_description",
                ty.documentation.as_deref(),
            );
            options.push_str(&format!(".with_source_map({source}.into())"));
            let mut expression = format!(
                "{query}.type_def().with_enum_opts({:?}, &{options})",
                ty.wire_name.as_str()
            );
            for value in &ty.enum_values {
                let mut member_options = format!("{alias}::TypeDefWithEnumMemberOpts::default()");
                append_string_option(
                    &mut member_options,
                    "with_description",
                    value.documentation.as_deref(),
                );
                append_string_option(
                    &mut member_options,
                    "with_deprecated",
                    value.deprecation.as_deref(),
                );
                member_options.push_str(&format!(
                    ".with_source_map({}.into())",
                    render_source_map(query, &value.source)
                ));
                expression.push_str(&format!(
                    ".with_enum_member_opts({:?}, &{member_options})",
                    value.wire_name.as_str()
                ));
            }
            expression
        }
        ProjectedTypeKind::Scalar => {
            let mut options = format!("{alias}::TypeDefWithScalarOpts::default()");
            append_string_option(
                &mut options,
                "with_description",
                ty.documentation.as_deref(),
            );
            format!(
                "{query}.type_def().with_scalar_opts({:?}, &{options})",
                ty.wire_name.as_str()
            )
        }
    }
}

fn render_field_options(field: &super::model::ProjectedField, alias: &str) -> String {
    let mut options = format!("{alias}::TypeDefWithFieldOpts::default()");
    append_string_option(
        &mut options,
        "with_description",
        field.documentation.as_deref(),
    );
    append_string_option(
        &mut options,
        "with_deprecated",
        field.deprecation.as_deref(),
    );
    options.push_str(&format!(
        ".with_source_map({}.into())",
        render_source_map("query", &field.source)
    ));
    options
}

fn render_function(
    owner: &str,
    function: &ProjectedFunction,
    descriptor: &ModuleDescriptor,
    alias: &str,
    constructor: bool,
) -> Result<String, ModuleDiagnosticSet> {
    let variable = if constructor {
        "function_constructor".to_owned()
    } else {
        format!(
            "function_{}",
            function.wire_name.as_str().to_ascii_lowercase()
        )
    };
    let name = if constructor {
        ""
    } else {
        function.wire_name.as_str()
    };
    let return_type = if constructor {
        format!("{owner}.clone()")
    } else {
        render_projected_type(&function.return_type, descriptor, alias)?
    };
    let mut output =
        format!("            let mut {variable} = query.function({name:?}, {return_type});\n");
    if let Some(documentation) = &function.documentation {
        output.push_str(&format!(
            "            {variable} = {variable}.with_description({documentation:?});\n"
        ));
    }
    if let Some(deprecation) = &function.deprecation {
        output.push_str(&format!(
            "            {variable} = {variable}.with_deprecated_opts(&{alias}::FunctionWithDeprecatedOpts::default().with_reason({deprecation:?}));\n"
        ));
    }
    match function.cache {
        CachePolicy::Default => {}
        CachePolicy::Never => output.push_str(&format!(
            "            {variable} = {variable}.with_cache_policy({alias}::FunctionCachePolicy::Never);\n"
        )),
        CachePolicy::PerSession => output.push_str(&format!(
            "            {variable} = {variable}.with_cache_policy({alias}::FunctionCachePolicy::PerSession);\n"
        )),
        CachePolicy::TimeToLive(seconds) => output.push_str(&format!(
            "            {variable} = {variable}.with_cache_policy_opts({alias}::FunctionCachePolicy::Default, &{alias}::FunctionWithCachePolicyOpts::default().with_time_to_live({:?}));\n",
            format!("{seconds}s")
        )),
    }
    let role_method = match function.role {
        FunctionRole::Ordinary => None,
        FunctionRole::Check => Some("with_check"),
        FunctionRole::Generator => Some("with_generator"),
        FunctionRole::Up => Some("with_up"),
    };
    if let Some(role_method) = role_method {
        output.push_str(&format!(
            "            {variable} = {variable}.{role_method}();\n"
        ));
    }
    output.push_str(&format!(
        "            {variable} = {variable}.with_source_map({});\n",
        render_source_map("query", &function.source)
    ));
    for argument in &function.arguments {
        output.push_str(&render_argument(&variable, argument, descriptor, alias)?);
    }
    let attach = if constructor {
        "with_constructor"
    } else {
        "with_function"
    };
    output.push_str(&format!(
        "            {owner} = {owner}.{attach}({variable});\n"
    ));
    Ok(output)
}

fn render_argument(
    function: &str,
    argument: &ProjectedArgument,
    descriptor: &ModuleDescriptor,
    alias: &str,
) -> Result<String, ModuleDiagnosticSet> {
    let mut options = format!("{alias}::FunctionWithArgOpts::default()");
    if let Some(default) = &argument.default {
        let encoded = serde_json::to_string(default).map_err(|_| singleton(generation_error()))?;
        options.push_str(&format!(
            ".with_default_value({alias}::Json::new({encoded:?}))"
        ));
    }
    append_string_option(
        &mut options,
        "with_default_path",
        argument.default_path.as_deref(),
    );
    append_string_option(
        &mut options,
        "with_default_address",
        argument.default_address.as_deref(),
    );
    if !argument.ignore.is_empty() {
        options.push_str(&format!(".with_ignore(vec!{:?})", argument.ignore));
    }
    append_string_option(
        &mut options,
        "with_description",
        argument.documentation.as_deref(),
    );
    append_string_option(
        &mut options,
        "with_deprecated",
        argument.deprecation.as_deref(),
    );
    options.push_str(&format!(
        ".with_source_map({}.into())",
        render_source_map("query", &argument.source)
    ));
    Ok(format!(
        "            {function} = {function}.with_arg_opts({:?}, {}, &{options});\n",
        argument.wire_name.as_str(),
        render_argument_type(argument, descriptor, alias)?
    ))
}

fn render_argument_type(
    argument: &ProjectedArgument,
    descriptor: &ModuleDescriptor,
    alias: &str,
) -> Result<String, ModuleDiagnosticSet> {
    let rendered = render_projected_type(&argument.ty, descriptor, alias)?;
    Ok(
        if argument.optional && !projected_type_is_optional(&argument.ty) {
            format!("{rendered}.with_optional(true)")
        } else {
            rendered
        },
    )
}

fn projected_type_is_optional(ty: &ProjectedType) -> bool {
    match ty {
        ProjectedType::Void => true,
        ProjectedType::List { nullable, .. } | ProjectedType::Named { nullable, .. } => *nullable,
    }
}

fn render_projected_type(
    ty: &ProjectedType,
    descriptor: &ModuleDescriptor,
    alias: &str,
) -> Result<String, ModuleDiagnosticSet> {
    let query = "query";
    let (base, nullable) = match ty {
        ProjectedType::Void => (
            format!("{query}.type_def().with_kind({alias}::TypeDefKind::VoidKind)"),
            true,
        ),
        ProjectedType::List { element, nullable } => (
            format!(
                "{query}.type_def().with_list_of({})",
                render_projected_type(element, descriptor, alias)?
            ),
            *nullable,
        ),
        ProjectedType::Named { name, nullable } => {
            let base = match name.as_str() {
                "String" => {
                    format!("{query}.type_def().with_kind({alias}::TypeDefKind::StringKind)")
                }
                "Integer" => {
                    format!("{query}.type_def().with_kind({alias}::TypeDefKind::IntegerKind)")
                }
                "Boolean" => {
                    format!("{query}.type_def().with_kind({alias}::TypeDefKind::BooleanKind)")
                }
                "Float" => format!("{query}.type_def().with_kind({alias}::TypeDefKind::FloatKind)"),
                name => match projected_named_kind(name, descriptor)? {
                    ProjectedTypeKind::Object => {
                        format!("{query}.type_def().with_object({name:?})")
                    }
                    ProjectedTypeKind::Interface => {
                        format!("{query}.type_def().with_interface({name:?})")
                    }
                    ProjectedTypeKind::Enum => {
                        format!("{query}.type_def().with_enum({name:?})")
                    }
                    ProjectedTypeKind::Scalar => {
                        format!("{query}.type_def().with_scalar({name:?})")
                    }
                },
            };
            (base, *nullable)
        }
    };
    Ok(if nullable {
        format!("{base}.with_optional(true)")
    } else {
        base
    })
}

fn projected_named_kind(
    name: &str,
    descriptor: &ModuleDescriptor,
) -> Result<ProjectedTypeKind, ModuleDiagnosticSet> {
    if let Some(local) = descriptor
        .types
        .iter()
        .find(|ty| ty.wire_name.as_str() == name)
    {
        return Ok(match local.kind {
            LocalTypeKind::Object { .. } => ProjectedTypeKind::Object,
            LocalTypeKind::Interface => ProjectedTypeKind::Interface,
            LocalTypeKind::Enum => ProjectedTypeKind::Enum,
            LocalTypeKind::Scalar { .. } => ProjectedTypeKind::Scalar,
        });
    }
    for function in &descriptor.functions {
        for argument in &function.compiled.arguments {
            if let Some(kind) = generated_type_kind(name, &argument.ty) {
                return Ok(kind);
            }
        }
        if let Some(kind) = generated_type_kind(name, function.compiled.return_type.success()) {
            return Ok(kind);
        }
    }
    Err(singleton(generation_error()))
}

fn generated_type_kind(name: &str, ty: &RustModuleType) -> Option<ProjectedTypeKind> {
    match ty {
        RustModuleType::GeneratedObject(candidate) if candidate == name => {
            Some(ProjectedTypeKind::Object)
        }
        RustModuleType::GeneratedInterface(candidate) if candidate == name => {
            Some(ProjectedTypeKind::Interface)
        }
        RustModuleType::List(inner) | RustModuleType::Optional(inner) => {
            generated_type_kind(name, inner)
        }
        _ => None,
    }
}

fn append_string_option(output: &mut String, method: &str, value: Option<&str>) {
    if let Some(value) = value {
        output.push_str(&format!(".{method}({value:?})"));
    }
}

fn render_source_map(query: &str, source: &SourceCoordinate) -> String {
    format!(
        "{query}.source_map({}, {:?}, {})",
        source.column.get(),
        source.path.as_str(),
        source.line.get()
    )
}

fn render_codecs(descriptor: &ModuleDescriptor) -> Result<Vec<u8>, ModuleDiagnosticSet> {
    let mut output = String::from("//! Generated descriptor-owned local value codecs.\n\n");
    for ty in &descriptor.types {
        match &ty.contract {
            LocalTypeContract::Object(contract) => render_object_codec(&mut output, contract),
            LocalTypeContract::Enum(contract) => render_enum_codec(&mut output, contract)?,
            LocalTypeContract::Scalar(contract) => render_scalar_codec(&mut output, contract),
            LocalTypeContract::Interface(_) => {}
        }
    }
    Ok(output.into_bytes())
}

fn render_object_codec(output: &mut String, contract: &super::types::ObjectContract) {
    let object_type = contract.symbol.as_str();
    output.push_str(&format!(
        "impl super::__private::ModuleInputCodec for {object_type} {{\n    fn decode_input(value: &super::__private::ModuleJson, context: &super::__private::ModuleContextBase) -> Result<Self, super::__private::DecodeError> {{\n        let object = value.as_json().as_object().ok_or(super::__private::DecodeError)?;\n"
    ));
    for (index, field) in contract.fields.iter().enumerate() {
        output.push_str(&format!(
            "        let value_{index} = <{} as super::__private::ModuleInputCodec>::decode_input(&super::__private::ModuleJson::new(object.get({:?}).cloned().ok_or(super::__private::DecodeError)?), context)?;\n",
            rust_type(&field.ty),
            field.wire_name.as_str()
        ));
    }
    let values = (0..contract.fields.len())
        .map(|index| format!("value_{index}"))
        .collect::<Vec<_>>();
    let state = tuple_expression(&values);
    output.push_str(&format!(
        "        Ok(<{object_type} as super::__private::ModuleObjectBridge>::from_persistent_state({state}))\n    }}\n}}\n\n"
    ));
    output.push_str(&format!(
        "impl super::__private::ModuleOutputCodec for {object_type} {{\n    fn encode_output<'a>(self, context: &'a super::__private::ModuleContextBase) -> super::__private::ModuleBoxFuture<'a, Result<super::__private::ModuleJson, super::__private::EncodeError>> where Self: 'a {{\n        Box::pin(async move {{\n            let {state} = <{object_type} as super::__private::ModuleObjectBridge>::into_persistent_state(self);\n            let mut object = super::__private::serde_json::Map::new();\n"
    ));
    for (index, field) in contract.fields.iter().enumerate() {
        output.push_str(&format!(
            "            object.insert({:?}.to_owned(), <{} as super::__private::ModuleOutputCodec>::encode_output(value_{index}, context).await?.into_json());\n",
            field.wire_name.as_str(),
            rust_type(&field.ty)
        ));
    }
    output.push_str("            Ok(super::__private::ModuleJson::new(super::__private::serde_json::Value::Object(object)))\n        })\n    }\n}\n\n");
}

fn render_enum_codec(
    output: &mut String,
    contract: &super::types::EnumContract,
) -> Result<(), ModuleDiagnosticSet> {
    let rust_type = contract.symbol.as_str();
    let members = contract.wire_members().map_err(singleton)?;
    output.push_str(&format!(
        "impl super::__private::ModuleInputCodec for {rust_type} {{\n    fn decode_input(value: &super::__private::ModuleJson, _context: &super::__private::ModuleContextBase) -> Result<Self, super::__private::DecodeError> {{\n        match value.as_json().as_str().ok_or(super::__private::DecodeError)? {{\n"
    ));
    for (variant, wire) in &members {
        output.push_str(&format!(
            "            {:?} => Ok({rust_type}::{variant}),\n",
            wire.as_str()
        ));
    }
    output
        .push_str("            _ => Err(super::__private::DecodeError),\n        }\n    }\n}\n\n");
    output.push_str(&format!(
        "impl super::__private::ModuleOutputCodec for {rust_type} {{\n    fn encode_output<'a>(self, _context: &'a super::__private::ModuleContextBase) -> super::__private::ModuleBoxFuture<'a, Result<super::__private::ModuleJson, super::__private::EncodeError>> where Self: 'a {{\n        Box::pin(async move {{\n            let value = match self {{\n"
    ));
    for (variant, wire) in &members {
        output.push_str(&format!(
            "                {rust_type}::{variant} => {:?},\n",
            wire.as_str()
        ));
    }
    output.push_str("            };\n            Ok(super::__private::ModuleJson::new(super::__private::serde_json::Value::String(value.to_owned())))\n        })\n    }\n}\n\n");
    Ok(())
}

fn render_scalar_codec(output: &mut String, contract: &super::types::ScalarContract) {
    let scalar_type = contract.symbol.as_str();
    let representation = rust_type(&contract.representation);
    output.push_str(&format!(
        "impl super::__private::ModuleInputCodec for {scalar_type} {{\n    fn decode_input(value: &super::__private::ModuleJson, context: &super::__private::ModuleContextBase) -> Result<Self, super::__private::DecodeError> {{\n        let value = <{representation} as super::__private::ModuleInputCodec>::decode_input(value, context)?;\n        Ok(<{scalar_type} as super::__private::ModuleScalarBridge>::from_representation(value))\n    }}\n}}\n\n"
    ));
    output.push_str(&format!(
        "impl super::__private::ModuleOutputCodec for {scalar_type} {{\n    fn encode_output<'a>(self, context: &'a super::__private::ModuleContextBase) -> super::__private::ModuleBoxFuture<'a, Result<super::__private::ModuleJson, super::__private::EncodeError>> where Self: 'a {{\n        let value = <{scalar_type} as super::__private::ModuleScalarBridge>::into_representation(self);\n        <{representation} as super::__private::ModuleOutputCodec>::encode_output(value, context)\n    }}\n}}\n\n"
    ));
}

fn tuple_expression(values: &[String]) -> String {
    match values {
        [] => "()".to_owned(),
        [value] => format!("({value},)"),
        _ => format!("({})", values.join(", ")),
    }
}

fn render_dispatch(descriptor: &ModuleDescriptor) -> Result<Vec<u8>, ModuleDiagnosticSet> {
    let mut output = String::from(
        "//! Generated closed typed dispatch registry.\n\n/// Exact descriptor-owned dispatch implementation.\npub struct GeneratedDispatchRegistry;\n\nimpl super::__private::DispatchRegistry for GeneratedDispatchRegistry {\n    fn descriptor(&self) -> &'static super::__private::ModuleDescriptorView { &super::module_descriptor::DESCRIPTOR }\n\n    fn registration(&self) -> &'static super::__private::RegistrationView { &super::module_registration::REGISTRATION }\n\n    fn invoke<'a>(&'a self, call: super::__private::PreparedCall, context: super::__private::ModuleContextBase) -> super::__private::ModuleBoxFuture<'a, Result<super::__private::ModuleJson, super::__private::InvocationError>> {\n        Box::pin(async move {\n            let super::__private::CallSelector::Invocation { parent_wire_name, function_wire_name } = call.identity.selector() else { return Err(super::__private::InvocationError::UnknownFunction); };\n            let coordinate = super::__private::CallCoordinate { parent_wire_name: parent_wire_name.as_str().to_owned(), function_wire_name: function_wire_name.as_str().to_owned() };\n            match parent_wire_name.as_str() {\n",
    );
    let mut parents = BTreeMap::<String, Vec<_>>::new();
    for function in &descriptor.functions {
        let parent = descriptor
            .types
            .iter()
            .find(|ty| ty.rust_symbol == function.parent)
            .ok_or_else(|| singleton(generation_error()))?;
        parents
            .entry(parent.wire_name.as_str().to_owned())
            .or_default()
            .push(function);
    }
    for (parent, functions) in parents {
        output.push_str(&format!(
            "                {parent:?} => match function_wire_name.as_str() {{\n"
        ));
        for function in functions {
            output.push_str(&format!(
                "                    {:?} => {{\n",
                function.wire_name.as_str()
            ));
            render_dispatch_arm(&mut output, function)?;
            output.push_str("                    }\n");
        }
        output.push_str("                    _ => Err(super::__private::InvocationError::UnknownFunction),\n                },\n");
    }
    output.push_str("                _ => Err(super::__private::InvocationError::UnknownParent),\n            }\n        })\n    }\n}\n");
    Ok(output.into_bytes())
}

fn render_dispatch_arm(
    output: &mut String,
    function: &super::model::FunctionDescriptor,
) -> Result<(), ModuleDiagnosticSet> {
    let fingerprint = function
        .fingerprint
        .as_u128()
        .map_err(|_| singleton(generation_error()))?;
    let parent = function.parent.as_str();
    output.push_str(&format!(
        "                        let _: super::__private::AuthoringFingerprint<{fingerprint}> = <{parent} as super::__private::ModuleMethodBridge<{fingerprint}>>::authoring_fingerprint();\n"
    ));
    if function.compiled.receiver == ReceiverKind::Shared {
        output.push_str(&format!(
            "                        let receiver = <{parent} as super::__private::ModuleInputCodec>::decode_input(call.parent.as_ref().ok_or_else(|| super::__private::InvocationError::ParentDecode(coordinate.clone()))?, &context).map_err(|_| super::__private::InvocationError::ParentDecode(coordinate.clone()))?;\n"
        ));
    }
    for (index, argument) in function.compiled.arguments.iter().enumerate() {
        output.push_str(&format!(
            "                        let argument_{index}: {} = <{} as super::__private::ModuleInputCodec>::decode_input(call.arguments.get({index}).ok_or_else(|| super::__private::InvocationError::ArgumentDecode {{ coordinate: coordinate.clone(), argument_wire_name: {:?}.to_owned() }})?, &context).map_err(|_| super::__private::InvocationError::ArgumentDecode {{ coordinate: coordinate.clone(), argument_wire_name: {:?}.to_owned() }})?;\n",
            rust_type(&argument.ty),
            rust_type(&argument.ty),
            argument.wire_name.as_str(),
            argument.wire_name.as_str()
        ));
    }
    let mut call_arguments = (0..function.compiled.arguments.len())
        .map(|index| format!("argument_{index}"))
        .collect::<Vec<_>>();
    if let Some(index) = function.compiled.context_index {
        output.push_str("                        let module_context = super::ModuleContext::from_base(context.clone());\n");
        call_arguments.insert(index, "module_context".to_owned());
    }
    let bridge = format!(
        "__dagger_bridge_{}_{}",
        function.compiled.rust_name, fingerprint
    );
    let receiver = if function.compiled.receiver == ReceiverKind::Shared {
        "receiver."
    } else {
        ""
    };
    let associated = if function.compiled.receiver == ReceiverKind::None {
        format!("{parent}::")
    } else {
        receiver.to_owned()
    };
    let await_suffix = if function.compiled.execution == ExecutionKind::Asynchronous {
        ".await"
    } else {
        ""
    };
    output.push_str(&format!(
        "                        let value = {associated}{bridge}({}){await_suffix}",
        call_arguments.join(", ")
    ));
    if matches!(
        function.compiled.return_type,
        FunctionReturn::Fallible { .. }
    ) {
        output.push_str(".map_err(super::__private::InvocationError::Application)?");
    }
    output.push_str(";\n");
    let success = function.compiled.return_type.success();
    output.push_str(&format!(
        "                        <{} as super::__private::ModuleOutputCodec>::encode_output(value, &context).await.map_err(|_| super::__private::InvocationError::Encode {{ coordinate, result_type: {:?}.to_owned() }})\n",
        rust_type(success),
        rust_type(success)
    ));
    Ok(())
}

fn render_binding_catalog(descriptor: &ModuleDescriptor) -> Result<Vec<u8>, ModuleDiagnosticSet> {
    #[derive(Serialize)]
    struct Binding<'a> {
        rust_symbol: &'a RustSymbol,
        wire_name: &'a str,
    }
    let bindings = descriptor
        .types
        .iter()
        .map(|ty| Binding {
            rust_symbol: &ty.rust_symbol,
            wire_name: ty.wire_name.as_str(),
        })
        .collect::<Vec<_>>();
    canonical_bytes(&bindings).map_err(|_| singleton(generation_error()))
}

fn render_entrypoint(descriptor: &ModuleDescriptor) -> Vec<u8> {
    let crate_name = descriptor.package.name.as_str().replace('-', "_");
    format!(
        "//! Generic private module entrypoint generated for the checked descriptor.\n\n\
         fn main() -> Result<(), Box<dyn ::std::error::Error + Send + Sync>> {{\n    let runtime = ::tokio::runtime::Builder::new_current_thread().enable_all().build()?;\n    runtime.block_on(async {{\n        {crate_name}::dagger_generated::__private::run_module_entrypoint(\n            {crate_name}::dagger_generated::GeneratedDispatchRegistry,\n            {crate_name}::dagger_generated::GeneratedRegistrationSink::new,\n        ).await?;\n        Ok(())\n    }})\n}}\n"
    )
    .into_bytes()
}

fn rust_type(ty: &RustModuleType) -> String {
    match ty {
        RustModuleType::String => "String".to_owned(),
        RustModuleType::Integer => "i64".to_owned(),
        RustModuleType::Boolean => "bool".to_owned(),
        RustModuleType::Float => "f64".to_owned(),
        RustModuleType::Void => "()".to_owned(),
        RustModuleType::List(inner) => format!("Vec<{}>", rust_type(inner)),
        RustModuleType::Optional(inner) => format!("Option<{}>", rust_type(inner)),
        RustModuleType::LocalObject(symbol)
        | RustModuleType::LocalInterface(symbol)
        | RustModuleType::LocalEnum(symbol)
        | RustModuleType::CustomScalar(symbol) => symbol.as_str().to_owned(),
        RustModuleType::GeneratedObject(name) | RustModuleType::GeneratedInterface(name) => {
            format!("crate::dagger_generated::{name}")
        }
    }
}

fn validate_alias(alias: &str) -> Result<(), ModuleDiagnosticSet> {
    let mut characters = alias.chars();
    if characters
        .next()
        .is_none_or(|character| character != '_' && !character.is_ascii_alphabetic())
        || !characters.all(|character| character == '_' || character.is_ascii_alphanumeric())
    {
        return Err(singleton(diag(
            ModuleDiagnosticCode::NameInvalid,
            "the selected SDK dependency alias is not a Rust identifier",
            "retain the exact validated Cargo dependency alias",
        )));
    }
    Ok(())
}

fn generation_error() -> ModuleDiagnostic {
    diag(
        ModuleDiagnosticCode::ModuleGenerationFailed,
        "generated module assets could not be rendered",
        "repair the descriptor or generator invariant before publication",
    )
}

fn diag(
    code: ModuleDiagnosticCode,
    message: &'static str,
    remediation: &'static str,
) -> ModuleDiagnostic {
    ModuleDiagnostic::new(code, None, message, remediation)
        .expect("static generation diagnostics satisfy the safe renderer policy")
}

fn singleton(diagnostic: ModuleDiagnostic) -> ModuleDiagnosticSet {
    ModuleDiagnosticSet::new(vec![diagnostic])
        .expect("a singleton generation diagnostic set is non-empty")
}

